<?php
require_once __DIR__.'/config/auth.php';$user=require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('archive_add.php');verify_csrf();$moved=[];$pdo=null;$ref=trim((string)($_POST['ref_number']??''));
try{$name=trim((string)($_POST['sender_name']??''));$phone=trim((string)($_POST['sender_phone']??''));$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);if($ref==='')throw new RuntimeException('Reference number is required.');if($name===''||$phone===''||$amount===false||$amount<=0)throw new RuntimeException('Sender name, phone, and an amount greater than zero are required.');$pdo=db();$s=$pdo->prepare('SELECT id FROM archives WHERE ref_number=?');$s->execute([$ref]);if($s->fetch())throw new RuntimeException('That reference number already exists.');if(!isset($_FILES['document_1'])||($_FILES['document_1']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)throw new RuntimeException('One document is required.');$path=upload_file($_FILES['document_1'],'documents');$moved[]=$path;$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO archives(ref_number,created_by,updated_by) VALUES(?,?,?)');$s->execute([$ref,$user['id'],$user['id']]);$archiveId=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO archive_documents(archive_id,slot_no,original_name,file_path) VALUES(?,?,?,?)');$s->execute([$archiveId,1,substr((string)$_FILES['document_1']['name'],0,255),$path]);$s=$pdo->prepare('INSERT INTO payments(archive_id,sender_name,sender_phone,amount,received_by) VALUES(?,?,?,?,?)');$s->execute([$archiveId,$name,$phone,number_format((float)$amount,2,'.',''),$user['id']]);$paymentId=(int)$pdo->lastInsertId();$pdo->commit();log_activity('archive created','archive',$archiveId,$ref,'Archive, document, and payment created',$user);log_activity('payment created','payment',$paymentId,$ref,'Payment recorded with archive',$user);redirect('archive_view.php?id='.$archiveId.'&saved=1');}catch(Throwable $e){if($pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();foreach($moved as $path)remove_file($path);$_SESSION['form_error']=$e instanceof RuntimeException?$e->getMessage():'The archive could not be saved. Nothing was stored.';$_SESSION['form_old']=['ref_number'=>$ref];redirect('archive_add.php');}
